import sys
from collections import defaultdict

def longestString(arr):
    arr_set = set(arr)
    arr.sort(key=lambda x: (-len(x), x))
    for s in arr:
        all_prefixes = True
        for i in range(1, len(s)):
            if s[:i] not in arr_set:
                all_prefixes = False
                break
        if all_prefixes:
            return s
    return ''

input = sys.stdin.read().strip().split()
print(longestString(input))
